const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
test('combined draft charges once and delivers each type to its selected fleet',()=>{const g=game();g.run('update=()=>save();state.resources={metal:10000000,crystal:10000000,eonium:10000000};state.productionDraft=[{id:"terran-lumen",qty:3,fleet:"f2"},{id:"terran-aegis",qty:2,fleet:"f3"}]');const before=g.run('state.resources.metal'),bill=g.run('productionDraftCost(state.productionDraft).metal'),f2=g.run('state.fleets.f2["terran-lumen"]||0'),f3=g.run('state.fleets.f3["terran-aegis"]||0');g.run('confirmShipDraft()');assert.equal(g.run('state.resources.metal'),before-bill);assert.equal(g.run('state.productionDraft.length'),0);g.run('state.production.remaining=1;tickOnce()');assert.equal(g.run('state.fleets.f2["terran-lumen"]'),f2+3);assert.equal(g.run('state.fleets.f3["terran-aegis"]'),f3+2);});
test('unaffordable draft is preserved without partial payment',()=>{const g=game();g.run('state.resources={metal:0,crystal:0,eonium:0};state.productionDraft=[{id:"terran-lumen",qty:200,fleet:"base"}];confirmShipDraft()');assert.equal(g.run('state.production'),null);assert.equal(g.run('state.productionDraft.length'),1);assert.equal(g.run('state.resources.metal'),0);});
test('combat news preserves arrived ships and exact losses and restores calculator inputs',()=>{const g=game();g.context.scrollTo=()=>{};g.run('const f=resolveCombat({"terran-lumen":40},{"terran-aegis":12});recordBattleNews({name:"Alpha"},{name:"Target",coords:"07:05:02"},f);renderNews()');assert.match(g.elements.get('newsLog').innerHTML,/Arrived/);assert.match(g.elements.get('newsLog').innerHTML,/Salvage report/);g.run('openBattleNews(state.news[0].battleReport.id)');assert.equal(g.run('window.bcalc.a["terran-lumen"]'),40);assert.equal(g.run('window.bcalc.d["terran-aegis"]'),12);assert.equal(g.run('state.news[0].battleReport.attacker["terran-lumen"]'),40);});
test('paused ticker freezes automatic ticks and manual step works',()=>{const g=game();g.run('update=()=>save();controlTicker("pause");state.nextTickAt=Date.now()-10000;updateCountdown()');assert.equal(g.run('state.tick'),1);g.run('controlTicker("step")');assert.equal(g.run('state.tick'),2);g.run('controlTicker("start")');assert.equal(g.run('state.config.tickerPaused'),false);assert.ok(g.run('state.nextTickAt>Date.now()'));g.document.getElementById('tickerMinutes').value='2';g.run('controlTicker("speed")');assert.equal(g.run('gameTickMs()'),120000);});
function game(saved,initialRender=false){
  const elements=new Map(),listeners={};const element=()=>({innerHTML:'',textContent:'',value:'',checked:false,dataset:{},style:{setProperty(){}},classList:{add(){},remove(){},toggle(){}},addEventListener(){},append(){},remove(){},setAttribute(){}});
  const document={getElementById(id){if(!elements.has(id))elements.set(id,element());return elements.get(id);},querySelector(){return null;},querySelectorAll(){return [];},createElement:element,body:element(),addEventListener(type,fn){(listeners[type]||=[]).push(fn);}};
  const store={};if(saved)store['starfall-round-v2']=JSON.stringify(saved);
  const context=vm.createContext({console,document,localStorage:{getItem:k=>store[k]||null,setItem:(k,v)=>store[k]=v},setTimeout(){},setInterval(){},confirm:()=>true,location:{hash:'',reload(){}},navigator:{}});context.window=context;
  vm.runInContext(fs.readFileSync(path.join(__dirname,'../dist/ship-catalog.js'),'utf8'),context);
  const source=fs.readFileSync(path.join(__dirname,'../dist/game.js'),'utf8').replace('normalizeGalaxySlots();update();setInterval(updateCountdown,1000);',initialRender?'normalizeGalaxySlots();update();setInterval(updateCountdown,1000);':'normalizeGalaxySlots();');vm.runInContext(source,context);
  return {context,document,elements,store,run:code=>vm.runInContext(code,context)};
}
test('migrates all existing planets into 1–10 without data loss',()=>{const g=game();assert.equal(g.run('state.galaxy.length'),15);assert.ok(g.run('state.galaxy.every(p=>Number(p.coords.split(":")[2])<=10)'));assert.equal(g.run('new Set(state.galaxy.map(p=>p.coords)).size'),15);assert.equal(g.run('state.alliance.members.find(m=>m.name==="Sera Dain").coords'),g.run('state.galaxy.find(p=>p.ruler==="Sera Dain").coords'));const before=g.run('JSON.stringify(state.galaxy)');g.run('normalizeGalaxySlots()');assert.equal(g.run('JSON.stringify(state.galaxy)'),before);});
test('all local, simulated and empty galaxies always render 15 slots',()=>{const g=game();for(const coords of ['{x:7,y:4}','{x:7,y:5}','{x:8,y:6}']){g.run(`state.browserCoords=${coords};renderGalaxyBrowser()`);assert.equal((g.elements.get('browserPlanetRows').innerHTML.match(/<tr/g)||[]).length,15);assert.equal((g.elements.get('browserPlanetMap').innerHTML.match(/class="planet-chip/g)||[]).length,15);assert.equal((g.elements.get('browserPlanetRows').innerHTML.match(/Empty \/ Reserved/g)||[]).length,5);}});
test('structure slots are exactly 11–15 and structures display without planet overlap',()=>{const g=game();g.run('state.alliance.fortress.strongholdGalaxy="07:04"');assert.equal(g.run('JSON.stringify(availableStructureSlots())'),'[11,12,13,14,15]');g.run('state.structurePlanets.push({id:"s1",name:"Dyson Sphere",slot:11,coords:"07:04:11",alliance:"Vesper Pact"});renderGalaxyBrowser()');const html=g.elements.get('browserPlanetRows').innerHTML;assert.match(html,/Dyson Sphere/);assert.equal((html.match(/<tr/g)||[]).length,15);assert.equal(g.run('JSON.stringify(availableStructureSlots())'),'[12,13,14,15]');});
test('self exile is unchecked, cancellable, moves to a different galaxy and preserves assets',()=>{const g=game();g.run('renderPlanetSettings()');assert.match(g.elements.get('planetSettingsContent').innerHTML,/EXILE OPTION/);assert.doesNotMatch(g.elements.get('planetSettingsContent').innerHTML,/id="selfExile"[^>]*checked/);g.run('state.resources={metal:100000,crystal:100000,eonium:100000}');const before=g.run('JSON.stringify(state)');const checkbox={checked:true};g.context.confirm=()=>false;g.run('requestSelfExile') (checkbox);assert.equal(checkbox.checked,false);assert.equal(g.run('JSON.stringify(state)'),before);g.context.confirm=()=>true;g.run('update=()=>save()');const cost=g.run('selfExileCost()');const resources=g.run('state.resources.metal');const assets=g.run('JSON.stringify([state.fleets,state.buildings,state.research,state.roids,state.population,state.missions])');checkbox.checked=true;g.run('requestSelfExile')(checkbox);assert.notEqual(g.run('homeGalaxy()'),'07:04');assert.equal(g.run('state.resources.metal'),resources-cost);assert.equal(g.run('state.selfExileCount'),1);assert.equal(g.run('state.galaxyFunds["07:04"].metal'),cost);assert.equal(g.run('JSON.stringify([state.fleets,state.buildings,state.research,state.roids,state.population,state.missions])'),assets);assert.equal(g.run('state.alliance.members.find(m=>m.name==="A. Commander").coords'),g.run('state.galaxy.find(p=>p.player).coords'));const saved=JSON.parse(g.store['starfall-round-v2']);assert.equal(game(saved).run('homeGalaxy()'),g.run('homeGalaxy()'));});
test('stronghold passive bonus and daily reward exclude remote and non-alliance planets',()=>{const g=game();g.run('state.alliance.fortress.strongholdGalaxy="07:04"');assert.equal(g.run('allianceIncomeMultiplier("A. Commander")'),1.0025);assert.equal(g.run('allianceIncomeMultiplier("Sera Dain")'),1);assert.equal(g.run('allianceIncomeMultiplier("Unknown")'),1);g.run('state.alliance.fortress.lastDistorterTick=1;state.tick=25;grantDailyDistorters()');assert.equal(g.run('state.buildings.waveDistorter'),1);assert.equal(g.run('state.galaxy.find(p=>p.ruler==="Nira Sol").waveDistorters'),1);assert.equal(g.run('state.galaxy.find(p=>p.ruler==="Sera Dain").waveDistorters||0'),0);g.run('grantDailyDistorters()');assert.equal(g.run('state.buildings.waveDistorter'),1);assert.match(g.run('allianceFortressHTML()'),/MEMBERS IN STRONGHOLD GALAXY/);g.run('movePlanet(state.galaxy.find(p=>p.player),"07:06:01")');assert.equal(g.run('allianceIncomeMultiplier("A. Commander")'),1);});
test('custom and paste coordinates validate, persist and remain beneath scan coordinates',()=>{const g=game();assert.equal(g.run('JSON.stringify(parseCustomScanCoordinates("2:7"))'),'{"x":"07","y":"02","z":"07"}');assert.equal(g.run('JSON.stringify(parseCustomScanCoordinates("08:06:15"))'),'{"x":"08","y":"06","z":"15"}');for(const text of ['2:16','0:1','<script>','2:7\n3:8'])assert.equal(g.run(`parseCustomScanCoordinates(${JSON.stringify(text)})`),null);g.run('renderWaves()');const html=g.elements.get('wavesContent').innerHTML;assert.ok(html.indexOf('customScanCoordinates')>html.indexOf('SCAN COORDINATES'));assert.match(html,/pasteScanCoordinates/);g.document.getElementById('pasteScanCoordinates').value='2:7';g.run('applyCustomScanCoordinates("paste")');assert.equal(g.run('state.waves.targetCoords.z'),'07');assert.match(g.elements.get('scanCoordinateFeedback').textContent,/07:02:07/);});
test('scan preserves prerequisites, charges once and stores report',()=>{const g=game();g.run('update=()=>save();state.waves.fundSources["A. Commander"]="personal";state.waves.targetCoords={x:"07",y:"04",z:"02"}');const before=g.run('state.resources.metal');g.run('runScan("planet")');assert.equal(g.run('state.resources.metal'),before);assert.equal(g.run('state.waves.scans.length'),0);g.run('state.buildings.waveAmplifier=1;runScan("planet")');assert.equal(g.run('state.waves.scans.length'),1);assert.ok(g.run('state.resources.metal')<before);assert.equal(g.run('state.waves.scans[0].coords'),'07:04:02');});
test('full rendering, hourly tick, economy, construction and research remain functional',()=>{const g=game();g.run('update()');assert.match(g.elements.get('wavesContent').innerHTML,/AVAILABLE SCANS/);assert.match(g.elements.get('shipCards').innerHTML,/ORDER NOW/);const before=g.run('state.resources.metal');g.run('tickOnce()');assert.equal(g.run('state.tick'),2);assert.ok(g.run('state.resources.metal')>before);assert.ok(g.run('Object.keys(SHIPS).length')>=36);});

test('manual self exile cost, free doubling, increasing costs and payment guards',()=>{const g=game();assert.equal(g.run('calculateSelfExileCost(10000,0,100,100)'),5000);assert.equal(g.run('calculateSelfExileCost(10000,0,100,100,true)'),10000);assert.equal(g.run('calculateSelfExileCost(10000,1,100,100)'),23627);g.run('renderPlanetSettings()');assert.match(g.elements.get('planetSettingsContent').innerHTML,/Planetarion cost formula/);g.run('update=()=>save();state.resources={metal:0,crystal:0,eonium:0}');const before=g.run('JSON.stringify(state)');g.run('requestSelfExile')({checked:true});assert.equal(g.run('JSON.stringify(state)'),before);g.run('state.resources={metal:100000,crystal:100000,eonium:100000};state.missions=[{id:"away",ships:{}}]');const coords=g.run('homeGalaxy()');g.run('requestSelfExile')({checked:true});assert.equal(g.run('homeGalaxy()'),coords);});

