test('Havoc applies global numbers instantly and reset restores the prior configuration after reload',()=>{const g=game();g.run('adminTab="havoc";update=()=>save();state.galaxy[1].race="Cathaar"');const before=g.run('JSON.stringify([state.resources,state.roids,state.fleets,state.research,state.buildings,state.config.tickHours,state.galaxy])');const html=g.run('adminHavocHTML()');assert.doesNotMatch(html,/id="havocPlanet"|LOAD CONFIGURATION/);assert.match(html,/RESET TO PREVIOUS/);for(const id of g.run('Object.keys(RES)')){g.document.getElementById('havocResource-'+id).value='12345';g.document.getElementById('havocRoids-'+id).value='42';}for(const t of g.run('TECH_TREE'))g.document.getElementById('admTech-'+t.id).value=t.max;for(const id of g.run('Object.keys(BUILDINGS)'))g.document.getElementById('admBuild-'+id).value='3';for(const cls of g.run('HAVOC_CLASSES'))g.document.getElementById('havocClass-'+cls).value='17';g.document.getElementById('havocTickMinutes').value='5';g.run('applyPlanetTools("all")');assert.ok(g.run('state.galaxy.every(p=>p.resources.metal===12345&&p.roids.metal===42)'));assert.equal(g.run('state.config.tickHours'),5/60);assert.ok(g.run('TECH_TREE.every(t=>state.research[t.id]===t.max)'));assert.ok(g.run('Object.values(state.buildings).every(n=>n===3)'));for(const cls of g.run('HAVOC_CLASSES')){const sum=g.run(`Object.entries(SHIPS).filter(([id,d])=>d.race===state.race&&d.class===${JSON.stringify(cls)}).reduce((n,[id])=>n+state.fleets.base[id],0)`);const exists=g.run(`Object.values(SHIPS).some(d=>d.race===state.race&&d.class===${JSON.stringify(cls)})`);assert.equal(sum,exists?17:0);}const restored=game(JSON.parse(g.store['starfall-round-v2']));restored.run('update=()=>save();resetHavoc()');assert.equal(restored.run('JSON.stringify([state.resources,state.roids,state.fleets,state.research,state.buildings,state.config.tickHours,state.galaxy])'),before);});
test('admin assigns an existing dummy and its member appears immediately',()=>{const g=game();g.run('window.isGameAdmin=true;window.scrollTo=()=>{}');g.document.getElementById('newAllianceName').value='Dummy Test';g.document.getElementById('newAllianceTag').value='DTEST';g.run('createAlliance()');const id=g.run('state.galaxy.find(p=>p.dummy).id');g.document.getElementById('allianceDummyPlanet').value=id;g.run('assignAllianceDummy()');assert.equal(g.run('state.alliance.members.length'),2);assert.match(g.run('allianceMembersHTML()'),/Practice Commander 1/);});
test('members exchange fund resources at five percent loss while preserving every reserve minimum',()=>{const g=game();g.run('update=()=>save();state.alliance.members.find(m=>m.name==="A. Commander").rank="Member";state.alliance.fund={metal:2000,crystal:1000,eonium:1000};state.alliance.fundMinimum={metal:1000,crystal:1000,eonium:1000}');assert.equal(g.run('mayAlliance("exchange")'),true);assert.equal(g.run('mayAlliance("fundMinimum")'),false);assert.match(g.run('allianceFundHTML()'),/MINIMUM FUND RESERVES/);for(const [id,value] of [['fundExchangePool','fund'],['fundExchangeFrom','metal'],['fundExchangeTo','crystal'],['fundExchangeAmount','1001']])g.document.getElementById(id).value=value;let before=g.run('JSON.stringify(state)');g.run('exchangeAllianceResources()');assert.equal(g.run('JSON.stringify(state)'),before);g.document.getElementById('fundExchangeAmount').value='1000';g.run('exchangeAllianceResources()');assert.equal(g.run('state.alliance.fund.metal'),1000);assert.equal(g.run('state.alliance.fund.crystal'),1950);before=g.run('JSON.stringify(state)');g.run('saveAllianceFundMinimum()');assert.equal(g.run('JSON.stringify(state)'),before);g.document.getElementById('fundExchangeFrom').value='invalid';g.run('exchangeAllianceResources()');assert.equal(g.run('JSON.stringify(state)'),before);});
test('rank permissions can grant and revoke HC actions for every rank and persist',()=>{const g=game();g.run('update=()=>save();state.alliance.members.find(m=>m.name==="A. Commander").rank="Officer"');assert.equal(g.run('mayAlliance("war")'),false);g.run('state.alliance.rankPermissions=defaultAlliancePermissions();state.alliance.rankPermissions.Officer.war=true');assert.equal(g.run('mayAlliance("war")'),true);g.run('allianceAction("toggleWar",{dataset:{war:"Test Enemy"}})');assert.ok(g.run('state.alliance.wars.includes("Test Enemy")'));g.run('state.alliance.rankPermissions.Officer.war=false');const before=g.run('JSON.stringify(state)');g.run('allianceAction("toggleWar",{dataset:{war:"Test Enemy"}})');assert.equal(g.run('JSON.stringify(state)'),before);g.run('save()');assert.equal(game(JSON.parse(g.store['starfall-round-v2'])).run('mayAlliance("war")'),false);assert.match(g.run('allianceRanksHTML()'),/Recruit/);});
test('donations are charged once, delayed eight ticks, and enforce cumulative limits',()=>{const g=game();g.run('update=()=>save();state.resources.metal=100000');g.document.getElementById('fundResource').value='metal';const cap=g.run('Math.floor(income().metal*2)');g.document.getElementById('fundAmount').value=String(cap);const fund=g.run('state.alliance.fund.metal');g.run('donateAllianceFund()');assert.equal(g.run('state.resources.metal'),100000-cap);assert.equal(g.run('state.alliance.fund.metal'),fund);assert.equal(g.run('state.alliance.pendingDonations.at(-1).tick'),g.run('state.tick')+8);const before=g.run('JSON.stringify(state)');g.document.getElementById('fundAmount').value='1';g.run('donateAllianceFund()');assert.equal(g.run('JSON.stringify(state)'),before);g.document.getElementById('fundAmount').value='0.5';g.run('donateAllianceFund()');assert.equal(g.run('JSON.stringify(state)'),before);});
