test('creating an alliance replaces the creation form with statistics and persists',()=>{const g=game();g.run('window.scrollTo=()=>{};renderCreatedAllianceStats()');assert.equal(g.document.getElementById('allianceCreatePanel').hidden,false);g.document.getElementById('newAllianceName').value='Stats Alliance';g.document.getElementById('newAllianceTag').value='STATS';g.run('createAlliance()');assert.equal(g.document.getElementById('allianceCreatePanel').hidden,true);assert.equal(g.document.getElementById('allianceStatistics').hidden,false);assert.match(g.document.getElementById('allianceStatistics').innerHTML,/Stats Alliance|FUND RESOURCES/);const restored=game(JSON.parse(g.store['starfall-round-v2']));restored.run('renderCreatedAllianceStats()');assert.equal(restored.document.getElementById('allianceCreatePanel').hidden,true);});
test('ordinary and alliance intel browsers share planet and structure data',()=>{const g=game();g.run('state.browserCoords={x:7,y:4};state.alliance.intelBrowserCoords={x:7,y:4};state.galaxy.find(p=>p.id==="ally1").name="Shared Planet Update";state.structurePlanets.push({id:"shared-structure",name:"Shared Stronghold",coords:"07:04:11",slot:11,alliance:state.alliance.name});renderGalaxyBrowser()');assert.match(g.document.getElementById('browserPlanetRows').innerHTML,/Shared Planet Update/);assert.match(g.run('allianceIntelHTML()'),/Shared Planet Update/);assert.match(g.document.getElementById('browserPlanetRows').innerHTML,/Shared Stronghold/);assert.match(g.run('allianceIntelHTML()'),/Shared Stronghold/);});

test('intel dropdowns include every alliance and relations color rows with latest scan links',()=>{const g=game();g.run('state.alliance.intelRecords={"07:04:02":{relation:"NAP",targetAlliance:"Ashen Banner"}};state.waves.scans=[{id:"p",coords:"07:04:02",type:"planet",name:"Planet scan",tick:5},{id:"old",coords:"07:04:02",type:"planet",tick:1}];');const html=g.run('allianceIntelHTML()');assert.match(html,/data-intel-affiliation="07:04:02"/);assert.match(html,/intel-relation-nap/);assert.match(html,/Latest scans/);assert.equal((html.match(/data-intel-scan-coords="07:04:02"/g)||[]).length,1);assert.match(html,/T5/);assert.match(html,/Ashen Banner/);g.run('state.alliance.rankPermissions={HC:{intelNotes:false}}');assert.match(g.run('allianceIntelHTML()'),/data-intel-affiliation="07:04:02" disabled/);});

test('fleet launch selectors start outbound missions and recall returns exactly those ships',()=>{for(const fid of ['f1','f2','f3']){const g=game();g.run('update=()=>save()');g.run('state.fleets['+JSON.stringify(fid)+'][Object.keys(SHIPS)[0]]=5');g.document.getElementById('missionFleet').value=fid;g.document.getElementById('missionTarget').value=g.run('state.galaxy.find(p=>!p.player).id');g.document.getElementById('missionType').value='Defence';const before=g.run('JSON.stringify(state.fleets['+JSON.stringify(fid)+'])');const count=g.run('totalShips(state.fleets['+JSON.stringify(fid)+'])');g.run('launchMission()');assert.equal(g.run('state.missions.length'),1);assert.equal(g.run('state.missions[0].fleet'),fid);assert.equal(g.run('state.missions[0].phase'),'outbound');assert.equal(g.run('totalShips(state.fleets['+JSON.stringify(fid)+'])'),0);assert.equal(g.run('totalShips(state.missions[0].ships)'),count);g.run('recallMission(state.missions[0].id);tickOnce()');assert.equal(g.run('state.missions.length'),0);assert.equal(g.run('JSON.stringify(state.fleets['+JSON.stringify(fid)+'])'),before);}const html=fs.readFileSync(path.join(__dirname,'../dist/index.html'),'utf8');for(const n of [1,2,3])assert.match(html,new RegExp('value="f'+n+'">Fleet '+n));});
test('launch protection and empty fleet guards preserve ships without creating orders',()=>{const g=game();g.run('update=()=>save()');g.document.getElementById('missionFleet').value='f1';g.document.getElementById('missionTarget').value=g.run('state.galaxy.find(p=>!p.player).id');g.document.getElementById('missionType').value='Attack';const before=g.run('JSON.stringify(state.fleets)');g.run('launchMission()');assert.equal(g.run('state.missions.length'),0);assert.equal(g.run('JSON.stringify(state.fleets)'),before);g.run('state.tick=30;state.fleets.f1=normalizeFleet({})');g.run('launchMission()');assert.equal(g.run('state.missions.length'),0);});

test('galaxy all scans preserves every report and charges the aggregate bill once',()=>{const g=game();g.run('update=()=>save();state.userSettings.allianceScansEnabled=true;state.buildings.waveAmplifier=1;state.research.scans=7;state.waves.galaxyScanType="all";state.resources={metal:1000000,crystal:1000000,eonium:1000000};state.waves.fundSources["A. Commander"]="personal"');const targets=g.run('state.galaxy.filter(p=>!p.player&&!p.exiled&&galaxyOf(p.coords)===homeGalaxy()).length'),bill=g.run('SCAN_TYPES.reduce((n,t)=>n+scanCost(t[2]),0)')*targets;g.run('runGalaxyScan()');assert.equal(g.run('state.waves.scans.length'),targets*8);assert.equal(g.run('new Set(state.waves.scans.map(s=>s.type)).size'),8);assert.equal(g.run('state.resources.metal'),1000000-bill);g.run('renderWaves()');assert.match(g.elements.get('wavesContent').innerHTML,/type="radio" name="galaxyScanType" value="all" checked/);assert.doesNotMatch(g.elements.get('wavesContent').innerHTML,/<select id="galaxyScanType"/);});
test('all scans skips locked types and insufficient funds leave the sweep untouched',()=>{const g=game();g.run('update=()=>save();state.userSettings.allianceScansEnabled=true;state.buildings.waveAmplifier=1;state.research.scans=1;state.waves.galaxyScanType="all";state.resources={metal:1000000,crystal:1000000,eonium:1000000};state.waves.fundSources["A. Commander"]="personal";runGalaxyScan()');assert.equal(g.run('new Set(state.waves.scans.map(s=>s.type)).size'),2);const before=g.run('state.waves.scans.length');g.run('state.resources={metal:0,crystal:0,eonium:0};runGalaxyScan()');assert.equal(g.run('state.waves.scans.length'),before);});

test('alliance intel relation is read-only and redundant dossier column is removed',()=>{const g=game();g.run('state.alliance.intelRecords={"07:04:02":{relation:"War"}}');const html=g.run('allianceIntelHTML()');assert.match(html,/intel-relation-text war/);assert.doesNotMatch(html,/data-intel-relation|OPEN INTEL|<th>Intel<\/th>/);assert.match(html,/data-intel-target="07:04:02"/);});

test('nickname column accepts labels and suggests members without assigned planets',()=>{const g=game();g.run('state.alliance.members.push({name:"Unassigned Scout",rank:"Member",planet:""});state.alliance.intelRecords={"07:04:02":{nickname:"Scout One"}}');const html=g.run('allianceIntelHTML()');assert.match(html,/<th>Nickname<\/th>/);assert.match(html,/data-intel-nickname="07:04:02"/);assert.match(html,/value="Scout One"/);assert.match(html,/<option value="Unassigned Scout">/);});

test('public username control is immediately beneath the planet display name placeholder',()=>{const g=game();g.run('renderPlanetSettings()');const html=g.elements.get('planetSettingsContent').innerHTML;assert.ok(html.indexOf('id="planetUsername"')>html.indexOf('Planet display name'));assert.ok(html.indexOf('id="planetUsername"')<html.indexOf('THEME SETTINGS'));g.document.getElementById('planetUsername').value='Star Captain';g.run('update=()=>save();savePlanetUsername()');assert.equal(g.run('state.galaxy.find(p=>p.player).username'),'Star Captain');});

test('galaxy intel overlay mirrors labels and relations without editable controls',()=>{const g=game();g.run('state.alliance.intelOverlay=true;state.alliance.intelRecords={"07:04:01":{nickname:"Captain",targetAlliance:"Vesper Pact",relation:"War",status:"Watch"}};var overlayRows=Array.from({length:15},()=>({html:"",classList:{add(){}},insertAdjacentHTML(pos,html){this.html+=html;}}));document.getElementById("browserPlanetRows").querySelectorAll=()=>overlayRows;renderGalaxyIntelOverlay()');const html=g.run('overlayRows[0].html');assert.match(html,/Captain/);assert.match(html,/Vesper Pact/);assert.match(html,/intel-relation-text war/);assert.doesNotMatch(html,/<input|<select|OPEN INTEL/);g.run('state.alliance.intelFields={HC:{assessment:false}};overlayRows.forEach(r=>r.html="");renderGalaxyIntelOverlay()');assert.doesNotMatch(g.run('overlayRows[0].html'),/Captain|Watch/);});

test('Apply to order number updates only active throughput and preserves paid progress',()=>{const g=game();g.run('update=()=>save();state.production={id:Object.keys(SHIPS)[0],qty:10,total:50000,remaining:30000,cost:{metal:100}};state.productionQueue=[{id:Object.keys(SHIPS)[0],qty:5,total:10000,remaining:10000,cost:{metal:50}}];normalizeFactoryAssignments()');const initial=g.run('productionRate()'),queue=g.run('JSON.stringify(state.productionQueue)'),money=g.run('JSON.stringify(state.resources)');g.run('state.buildings.lightFactory=20;state.factoryAssignments.lightFactory=20');assert.equal(g.run('productionRate()'),initial);g.run('applyFactoriesToOrder(state.production.orderNumber)');assert.ok(g.run('productionRate()')>initial);assert.equal(g.run('state.production.remaining'),30000);assert.equal(g.run('JSON.stringify(state.productionQueue)'),queue);assert.equal(g.run('JSON.stringify(state.resources)'),money);const rate=g.run('productionRate()');g.run('tickOnce()');assert.equal(g.run('state.production.remaining'),30000-rate);assert.match(g.run('productionFactoryHTML()'),/APPLY TO ORDER #/);});

test('admin assignments synchronize non-current alliances and retain rank across renamed planets',()=>{const g=game();g.run('update=()=>save();var p=state.galaxy.find(p=>!p.player);var before=copy(p);p.alliance="Other Alliance";syncEditedAllianceMember(p,before);reconcileAllianceMembers()');assert.equal(g.run('allianceProfile("Other Alliance").members.filter(m=>m.planetId===p.id).length'),1);assert.equal(g.run('state.alliance.members.filter(m=>m.planetId===p.id||m.planet===p.name).length'),0);g.run('allianceProfile("Other Alliance").members[0].rank="Officer";before=copy(p);p.name="Renamed Planet";p.ruler="Renamed Commander";syncEditedAllianceMember(p,before)');assert.equal(g.run('allianceProfile("Other Alliance").members[0].rank'),'Officer');assert.equal(g.run('allianceProfile("Other Alliance").members[0].planet'),'Renamed Planet');g.run('state.alliance.members=[];p.alliance=state.alliance.name;reconcileAllianceMembers()');assert.ok(g.run('state.alliance.members.some(m=>m.planetId===p.id)'));});

test('planet editor has separate modules and applying resources leaves other edits untouched',()=>{const g=game();g.context.isGameAdmin=true;g.run('state.adminSelected="ally1";adminTab="planets";renderAdmin()');const html=g.elements.get('adminContent').innerHTML;assert.equal((html.match(/data-apply-planet-module=/g)||[]).length,9);assert.doesNotMatch(html,/SAVE PLANET/);g.document.getElementById('admName').value='Unsaved name';for(const r of ['metal','crystal','eonium'])g.document.getElementById('admRes-'+r).value='100';const before=g.run('JSON.stringify([state.galaxy[1].name,state.galaxy[1].alliance,state.galaxy[1].coords,state.galaxy[1].roids,state.galaxy[1].ships])');g.run('applyAdminPlanetModule("resources")');assert.equal(g.run('JSON.stringify(state.galaxy[1].resources)'),'{"metal":100,"crystal":100,"eonium":100}');assert.equal(g.run('JSON.stringify([state.galaxy[1].name,state.galaxy[1].alliance,state.galaxy[1].coords,state.galaxy[1].roids,state.galaxy[1].ships])'),before);});
test('module validation is atomic and location applies without reading identity or economy inputs',()=>{const g=game();g.context.isGameAdmin=true;g.run('update=()=>save();state.adminSelected="ally1"');const before=g.run('JSON.stringify(state.galaxy[1])');g.document.getElementById('admRes-metal').value='300';g.document.getElementById('admRes-crystal').value='-1';g.document.getElementById('admRes-eonium').value='300';g.run('applyAdminPlanetModule("resources")');assert.equal(g.run('JSON.stringify(state.galaxy[1])'),before);for(const [id,n] of [['admCoordX','8'],['admCoordY','3'],['admCoordZ','2']])g.document.getElementById(id).value=n;g.run('applyAdminPlanetModule("location")');assert.equal(g.run('state.galaxy[1].coords'),'08:03:02');assert.equal(g.run('state.alliance.members.find(m=>m.planetId===state.galaxy[1].id).coords'),'08:03:02');});

test('shared round reset restores race and canonical fleet ids for editor modules',()=>{const g=game();g.run(fs.readFileSync(path.join(__dirname,'../dist/planets.js'),'utf8').replace('initializePlanetDirectory();setInterval(refreshSharedPlanets,15000);',''));g.run('var defaults=freshState();var data={userId:"admin",revision:1,resetGeneration:1,canEdit:true,planets:defaults.galaxy,structures:[],alliances:[defaults.alliance]};applySharedDirectory(data)');assert.equal(g.run('state.race'),'Terran');assert.ok(g.run('Object.keys(state.fleets.base).every(id=>SHIPS[id])'));assert.match(g.run('adminPlanetEditorHTML(state.galaxy.find(p=>p.player))'),/admShip-terran-/);});

test('round state includes a separate reset panel and explicit confirmation stage',()=>{const g=game();g.run('adminTab="state";renderAdmin()');const html=g.elements.get('adminContent').innerHTML;assert.match(html,/round-state-reset/);assert.match(html,/data-open-round-reset>RESET ROUND/);assert.match(html,/Accounts and passwords remain/);const source=fs.readFileSync(path.join(__dirname,'../dist/game.js'),'utf8');assert.match(source,/ARE YOU SURE\? RESET ROUND/);assert.match(source,/gameResetConfirmation/);});

test('whole-round reset clears claimed quests and restores default progress',()=>{const g=game();g.run(fs.readFileSync(path.join(__dirname,'../dist/planets.js'),'utf8').replace('initializePlanetDirectory();setInterval(refreshSharedPlanets,15000);',''));g.run('state.questClaims={lightfactory:true,scans25:true};state.xp=900;state.waves.scans=[{type:"planet"}];var defaults=freshState();applySharedDirectory({userId:"admin",revision:2,resetGeneration:2,canEdit:true,planets:defaults.galaxy,structures:[],alliances:[defaults.alliance]})');assert.equal(g.run('Object.keys(state.questClaims).length'),0);assert.equal(g.run('state.xp'),0);assert.equal(g.run('state.waves.scans.length'),0);assert.doesNotMatch(g.run('questRows()'),/quest-title">✓ /);assert.doesNotMatch(g.run('questRows()'),/>CLAIMED</);});

test('population and government bonuses are additive and update active ship work without repricing',()=>{const g=game();g.run('update=()=>save();state.production={id:Object.keys(SHIPS)[0],qty:10,total:100000,remaining:90000,cost:{metal:5000,crystal:3000,eonium:1000},factoryAssignments:{lightFactory:1,mediumFactory:0,heavyFactory:0}};state.workforce.shipwright=15;state.government="Socialism"');assert.equal(g.run('productionRate()'),Math.floor(115*1.35));const paid=g.run('JSON.stringify(state.production.cost)'),remaining=g.run('state.production.remaining');g.run('state.workforce.shipwright=40');assert.equal(g.run('productionRate()'),Math.floor(115*1.6));g.run('tickOnce()');assert.equal(g.run('state.production.remaining'),remaining-Math.floor(115*1.6));assert.equal(g.run('JSON.stringify(state.production.cost)'),paid);g.run('state.government="Nationalism";state.workforce.shipwright=0');assert.equal(g.run('productionRate()'),Math.floor(115*.9));});
test('government cost reduction charges new orders correctly and keeps existing orders paid prices',()=>{const g=game();g.run('update=()=>save();state.government="Democracy";state.resources={metal:10000000,crystal:10000000,eonium:10000000};var id=Object.keys(SHIPS).find(id=>SHIPS[id].race==="Terran"&&SHIPS[id].class==="Fighter")');const id=g.run('id');g.document.getElementById('qty-'+id).value='10';const cost=g.run('JSON.stringify(shipProductionCost(id))');g.run('orderShips(id)');for(const [r,n] of Object.entries(JSON.parse(cost)))assert.equal(g.run('state.resources['+JSON.stringify(r)+']'),10000000-n*10);const paid=g.run('JSON.stringify(state.production.cost)');g.run('state.government="Totalitarianism"');assert.equal(g.run('JSON.stringify(state.production.cost)'),paid);assert.equal(g.run('governmentProduction().cost'),6);});
test('government formation and revolution apply manual production penalties with persistent lookup',()=>{const g=game();g.run('update=()=>save()');g.document.getElementById('governmentSelect').value='Socialism';g.run('saveGovernment()');assert.equal(g.run('currentGovernmentName()'),'Socialism');g.context.confirm=()=>false;g.document.getElementById('governmentSelect').value='Democracy';g.run('saveGovernment()');assert.equal(g.run('currentGovernmentName()'),'Socialism');g.context.confirm=()=>true;g.run('saveGovernment()');assert.equal(g.run('currentGovernmentName()'),'Anarchy');assert.equal(g.run('state.governmentRevolutionUntil-state.tick'),72);g.run('state.tick=state.governmentRevolutionUntil');assert.equal(g.run('currentGovernmentName()'),'Democracy');assert.match(g.run('governmentHTML()'),/Government|GOVERNMENT LOOKUP/);assert.equal(game(JSON.parse(g.store['starfall-round-v2'])).run('state.governmentPending'),'Democracy');});

test('quest rewards bank once, survive reload and accept resources once',()=>{const g=game();g.run('update=()=>save();state.startupBonusGranted=true;var q=QUEST_CATEGORIES.flatMap(c=>c.quests).find(q=>q[3]==="building:lightFactory");claimQuest(q[0])');assert.equal(g.run('questBonusBank().metal'),500);g.run('claimQuest(q[0])');assert.equal(g.run('questBonusBank().metal'),500);const reloaded=game(JSON.parse(g.store['starfall-round-v2']));assert.equal(reloaded.run('questBonusBank().metal'),500);const before=g.run('state.resources.metal');g.run('allocateQuestBonus("accept")');assert.equal(g.run('state.resources.metal'),before+500);g.run('allocateQuestBonus("accept")');assert.equal(g.run('state.resources.metal'),before+500);assert.match(g.run('questRows()'),/REWARD/);});
test('bonus allocation validates the full budget and supports multiple research levels and partial buildings',()=>{const g=game();g.run('update=()=>save();questBonusBank().research=100000;questBonusBank().construction=700;var branch=TECH_TREE.find(t=>researchMax(t.id)>2).id;state.research[branch]=0;state.researchProgress[branch]=0;var needed=researchCost(branch,1)+researchCost(branch,2)');const branch=g.run('branch'),needed=g.run('needed');g.document.querySelectorAll=selector=>selector==='[data-bonus-rp]'?[{dataset:{bonusRp:branch},value:String(needed)}]:[{dataset:{bonusCu:'lightFactory'},value:'700'}];g.run('allocateQuestBonus("research")');assert.equal(g.run('state.research[branch]'),2);assert.equal(g.run('questBonusBank().research'),100000-needed);const before=g.run('state.buildings.lightFactory');g.run('allocateQuestBonus("construction")');assert.equal(g.run('state.buildings.lightFactory'),before+1);assert.equal(g.run('state.bonusConstructionProgress.lightFactory'),200);g.document.querySelectorAll=()=>[{dataset:{bonusCu:'lightFactory'},value:'1'}];g.run('allocateQuestBonus("construction")');assert.equal(g.run('state.bonusConstructionProgress.lightFactory'),200);});

test('startup bonus matches Planetarion base and race adjustments without repeat grants',()=>{const g=game();assert.equal(g.run('questBonusBank().metal'),2000000);assert.equal(g.run('questBonusBank().construction'),8750);assert.equal(g.run('questBonusBank().research'),7600);g.run('allocateQuestBonus("accept")');assert.equal(g.run('questBonusBank().metal'),0);const reloaded=game(JSON.parse(g.store['starfall-round-v2']));assert.equal(reloaded.run('questBonusBank().metal'),0);assert.equal(reloaded.run('questBonusBank().research'),7600);});

test('covert operations enforce protection, agents and research, charge once and produce filtered reports',()=>{const g=game();g.run('update=()=>save();state.resources={metal:100000,crystal:100000,eonium:100000};covertState().agents=30;var target=state.galaxy.find(p=>!p.player);target.roids={metal:6,crystal:6,eonium:6};target.covertAlert=0');g.document.getElementById('covertTarget').value=g.run('target.id');g.document.getElementById('covertOperation').value='fist';g.document.getElementById('covertSendAmount').value='9';g.run('executeCovert()');assert.equal(g.run('state.resources.metal'),100000);g.run('state.tick=25;covertState().stealth=80;Math.random=()=>.99;executeCovert()');assert.equal(g.run('state.resources.metal'),95500);assert.equal(g.run('totalRoids(target.roids)'),15);assert.equal(g.run('covertState().history.length'),1);assert.equal(g.run('state.news[0].category'),'COVERT_OPS');assert.equal(g.run('newsTintClass(state.news[0])'),'news-covert');g.run('state.newsCategories.COVERT_OPS=false;renderNews()');assert.doesNotMatch(g.elements.get('newsLog').innerHTML,/Covert operation Exploding/);g.document.getElementById('covertOperation').value='guards';g.run('executeCovert()');assert.equal(g.run('state.resources.metal'),95500);});
test('failed covert operations still charge and stealth recovers with wages on ticks',()=>{const g=game();g.run('update=()=>save();state.tick=25;state.resources={metal:100000,crystal:100000,eonium:100000};covertState().agents=20;covertState().stealth=80;var target=state.galaxy.find(p=>!p.player);target.covertAlert=200;Math.random=()=>.99');g.document.getElementById('covertTarget').value=g.run('target.id');g.document.getElementById('covertOperation').value='fist';g.document.getElementById('covertSendAmount').value='9';g.run('executeCovert()');assert.equal(g.run('covertState().history[0].success'),false);assert.equal(g.run('state.resources.metal'),95500);const stealth=g.run('covertState().stealth');g.run('tickCovert()');assert.ok(g.run('covertState().stealth')>stealth);assert.equal(g.run('state.resources.metal'),95480);});

test('fresh reset leaves all tax and scan sharing controls unchecked in one box',()=>{const g=game();assert.equal(g.run('state.userSettings.allianceTaxEnabled'),false);assert.equal(g.run('state.userSettings.allianceScansEnabled'),false);assert.equal(g.run('state.userSettings.shareScansToAll'),false);g.run('renderPlanetSettings()');const html=g.elements.get('planetSettingsContent').innerHTML;assert.equal((html.match(/class="quick-scan-sharing"/g)||[]).length,1);assert.doesNotMatch(html,/data-quick-setting="allianceTaxEnabled" checked/);assert.doesNotMatch(html,/data-quick-setting="allianceScansEnabled" checked/);});

test('full initial page boot renders covert, quests and news without late-constant errors',()=>{const g=game(undefined,true);assert.match(g.elements.get('covertContent').innerHTML,/OPERATION ORDERS/);assert.match(g.elements.get('questContent').innerHTML,/Temporal command/);assert.match(g.elements.get('newsLog').innerHTML,/news-log/);});
test('first ticker start, stop and restart unlock one-time asteroid rewards and game notices',()=>{const g=game();g.run('update=()=>save();controlTicker("start")');assert.equal(g.run('questValue("ticker:start")'),1);g.run('controlTicker("stop")');assert.equal(g.run('questValue("ticker:stop")'),1);assert.equal(g.run('state.config.tickerStopped'),true);g.run('controlTicker("start")');assert.equal(g.run('questValue("ticker:restart")'),1);assert.equal(g.run('state.news[0].category'),'GAME_UPDATES');g.run('state.startupBonusGranted=true;state.questBonuses={metal:0,crystal:0,eonium:0,research:0,construction:0,roids:{metal:0,crystal:0,eonium:0}};claimQuest("tickerFirstStart");claimQuest("tickerFirstStop");claimQuest("tickerFirstRestart");claimQuest("tickerFirstRestart")');assert.equal(g.run('questBonusBank().roids.metal'),3);assert.equal(g.run('questBonusBank().roids.crystal'),3);assert.equal(g.run('questBonusBank().roids.eonium'),3);assert.equal(g.run('questBonusBank().metal'),0);});

test('scheduled ticker starts once without unlocking any ticker quests',()=>{const g=game();g.run('update=()=>save();state.config.tickerPaused=true;state.config.tickerStopped=true;state.config.tickerAutoStartAt=Date.now()-100;processTickerAutoStart()');assert.equal(g.run('state.config.tickerPaused'),false);assert.equal(g.run('state.config.tickerAutoStartAt'),null);assert.equal(g.run('questValue("ticker:start")'),0);assert.equal(g.run('questValue("ticker:restart")'),0);assert.equal(g.run('state.news[0].category'),'GAME_UPDATES');const count=g.run('state.news.length');g.run('processTickerAutoStart()');assert.equal(g.run('state.news.length'),count);});

test('asteroid draft confirms atomically and preserves draft on insufficient resources',()=>{const g=game();g.run('update=()=>save();state.asteroidDraft={metal:2,crystal:3};state.resources={metal:100000,crystal:0,eonium:100000};confirmAsteroidDraft()');assert.equal(g.run('state.roids.metal'),6);assert.equal(g.run('state.resources.metal'),100000);assert.equal(g.run('state.asteroidDraft.metal'),2);const bill=g.run('asteroidDraftBill().metal');g.run('state.resources.crystal=100000;confirmAsteroidDraft()');assert.equal(g.run('state.roids.metal'),8);assert.equal(g.run('state.roids.crystal'),9);assert.equal(g.run('state.resources.metal'),100000-bill);assert.equal(g.run('Object.keys(state.asteroidDraft).length'),0);assert.match(g.run('miningCards()'),/ADD TO ORDER/);});

test('bulk quest claims include only completed unclaimed goals and do not duplicate rewards',()=>{const g=game();g.run('update=()=>save();state.startupBonusGranted=true;claimCompletedQuests("defense")');const claims=g.run('Object.keys(state.questClaims).length'),bank=g.run('questBonusBank().metal');assert.ok(claims>0);g.run('claimCompletedQuests("defense")');assert.equal(g.run('questBonusBank().metal'),bank);assert.equal(g.run('Object.keys(state.questClaims).length'),claims);g.run('claimCompletedQuests()');assert.ok(g.run('Object.keys(state.questClaims).length')>=claims);assert.equal(g.run('state.questClaims.tickerFirstStart||false'),false);});

test('automatic claiming is opt-in and banks completed rewards only once',()=>{const g=game();assert.equal(g.run('state.userSettings.autoClaimQuests'),false);g.run('state.startupBonusGranted=true;state.userSettings.autoClaimQuests=true');assert.ok(g.run('autoClaimQuestRewards()')>0);const bank=g.run('questBonusBank().metal');assert.equal(g.run('autoClaimQuestRewards()'),0);assert.equal(g.run('questBonusBank().metal'),bank);assert.equal(g.run('state.questClaims.tickerFirstStart||false'),false);});

test('universe uses alliance labels only from enabled, permitted intel',()=>{const g=game();g.run('renderUniverse()');assert.equal(g.document.getElementById('universeAllianceFilter').hidden,true);g.run('state.universeIntelOverlay=true;state.universeIntelOwner=state.alliance.name;state.universeIntelRecords={"07:04:02":{targetAlliance:"Private Intel Label"}};renderUniverse()');assert.equal(g.document.getElementById('universeAllianceFilter').hidden,false);assert.match(g.document.getElementById('universeTable').innerHTML,/Private Intel Label/);assert.doesNotMatch(g.document.getElementById('universeTable').innerHTML,/>Vesper Pact</);g.run('state.universeIntelOverlay=false;renderUniverse()');assert.doesNotMatch(g.document.getElementById('universeTable').innerHTML,/Private Intel Label/);});
test('fleet appearance renames heroes and restores names without changing stats',()=>{const g=game();const original=g.run('JSON.stringify(SHIPS)');g.run('state.userSettings.trekFleetEnabled=true;state.userSettings.trekFleetPower="Federation";applyTrekFleetNames()');assert.match(g.run('shipCards()'),/HERO/);assert.match(g.run('shipCards()'),/USS/);const unchanged=g.run('Object.entries(SHIPS).every(([id,d])=>{const old=JSON.parse('+JSON.stringify(original)+')[id];return d.armour===old.armour&&d.damage===old.damage&&JSON.stringify(d.cost)===JSON.stringify(old.cost);})');assert.equal(unchanged,true);g.run('state.userSettings.trekFleetEnabled=false;applyTrekFleetNames()');assert.equal(g.run('JSON.stringify(SHIPS)'),original);});
test('fleet class transfers move only matching ships and clamp each group amount',()=>{const g=game();const ids=g.run('Object.keys(SHIPS).filter(id=>SHIPS[id].race===state.race&&SHIPS[id].class==="Fighter")');g.run('state.fleets.base=normalizeFleet({});state.fleets.f1=normalizeFleet({});update=()=>save()');g.run('state.fleets.base['+JSON.stringify(ids[0])+']=12');g.document.getElementById('transferShip').value='group:Fighter';g.document.getElementById('transferFrom').value='base';g.document.getElementById('transferTo').value='f1';g.document.getElementById('transferAmount').value='100';g.run('transferShips()');assert.equal(g.run('state.fleets.f1['+JSON.stringify(ids[0])+']'),12);assert.equal(g.run('state.fleets.base['+JSON.stringify(ids[0])+']'),0);});
test('central reset clears every enabled preference before syncing dirty local data',()=>{const g=game();g.run(fs.readFileSync(path.join(__dirname,'../dist/planets.js'),'utf8').replace('initializePlanetDirectory();setInterval(refreshSharedPlanets,15000);',''));g.run('state.userSettings.allianceTaxEnabled=true;state.userSettings.allianceScansEnabled=true;state.userSettings.shareScansToAll=true;state.userSettings.autoClaimQuests=true;var defaults=freshState();applySharedDirectory({userId:"admin",revision:3,resetGeneration:3,canEdit:true,planets:defaults.galaxy,structures:[],alliances:[defaults.alliance]})');for(const key of ['allianceTaxEnabled','allianceScansEnabled','shareScansToAll','autoClaimQuests'])assert.equal(g.run('state.userSettings.'+key),false);});
test('universe modules track real tick changes and hide alliances without intel',()=>{const g=game();g.run('renderUniverseModules()');assert.match(g.elements.get('universeModules').innerHTML,/TOP PLANETS/);assert.match(g.elements.get('universeModules').innerHTML,/TOP GALAXIES/);assert.doesNotMatch(g.elements.get('universeModules').innerHTML,/ALLIANCES · PRIVATE INTEL/);g.run('state.tick+=1;state.roids.metal+=3;renderUniverseModules()');assert.match(g.elements.get('universeModules').innerHTML,/\+3/);assert.equal(g.run('state.universeHistory.length'),2);g.run('state.universeIntelOverlay=true;state.universeIntelOwner=state.alliance.name;state.universeIntelRecords={"07:04:01":{targetAlliance:state.alliance.name}};renderUniverseModules()');assert.match(g.elements.get('universeModules').innerHTML,/ALLIANCES · PRIVATE INTEL/);});
test('overview identity follows current planet settings',()=>{const g=game();g.run('var home=state.galaxy.find(p=>p.player);home.name="Nova Prime";home.ruler="Admiral Sol";home.username="Star Captain";updateHomeCoordinates()');assert.equal(g.elements.get('homeHeroTitle').textContent,'Nova Prime, under your command.');assert.match(g.elements.get('homeHeroDescription').textContent,/Admiral Sol.*Star Captain/);assert.equal(g.elements.get('homeSceneName').textContent,'Nova Prime');});
test('every alliance structure waits three ticks and charges only once',()=>{for(const type of ['transwarpHub','dysonSphere','ancientWeapons','voyagerIV','solarFlares']){const g=game();g.run('update=()=>save();state.alliance.fortress.strongholdGalaxy="07:04";state.alliance.tax=10;state.alliance.fund={metal:10000000,crystal:10000000,eonium:10000000}');const before=g.run('state.alliance.fund.metal');g.run('queueAllianceStructure('+JSON.stringify(type)+',11)');const paid=g.run('state.alliance.fund.metal');assert.ok(paid<before);g.run('queueAllianceStructure('+JSON.stringify(type)+',12)');assert.equal(g.run('state.alliance.fund.metal'),paid);assert.equal(g.run('state.alliance.structures.active.length'),0);g.run('state.tick+=2;processAllianceStructures()');assert.equal(g.run('state.alliance.structures.active.length'),0);assert.equal(g.run('state.alliance.structures.buildQueue.length'),1);g.run('state.tick+=1;processAllianceStructures()');assert.equal(g.run('state.alliance.structures.buildQueue.length'),0);if(['voyagerIV','solarFlares'].includes(type))assert.equal(g.run('state.structurePlanets.some(p=>p.building)'),false);else assert.equal(g.run('state.alliance.structures.active.some(p=>p.type==='+JSON.stringify(type)+')'),true);g.run('renderOverviewAllianceStructures()');assert.match(g.elements.get('overviewAllianceStructures').innerHTML,/ALLIANCE STRUCTURES/);}});
test('renaming a commander does not lose the account-owned alliance rank',()=>{const g=game();g.run('var home=state.galaxy.find(p=>p.player),member=state.alliance.members.find(m=>m.planet===home.name);member.planetId=home.id;home.name="Nova Prime";member.planet="Nova Prime";member.name="Star Captain"');assert.equal(g.run('currentAllianceRank()'),'HC');assert.equal(g.run('mayAlliance("structures")'),true);});
